/**
 * Returns a prime number which is >= desiredCapacity and very close to
 * desiredCapacity (within 11% if desiredCapacity >= 1000).
 * @param desiredCapacity the capacity desired by the user.
 * @return the capacity which should be used for a hashtable.
 */
public static int nextPrime(int desiredCapacity) {
    int primeCapacity = 11;

    if (desiredCapacity >= 1000) {
        primeCapacity = (int) (desiredCapacity * 1.11);
    } else {
        primeCapacity = desiredCapacity;
    }

    // Check if the capacity is prime
    if (isPrime(primeCapacity)) {
        return primeCapacity;
    } else {
        // If the capacity is not prime, find the next prime number
        int nextPrime = primeCapacity + 1;
        while (!isPrime(nextPrime)) {
            nextPrime++;
        }
        return nextPrime;
    }
}

