public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    ThreadSnapshot lastThreadSnapshot = null;

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("HEAP DUMP:")) {
                // Parse the heap dump line
                String[] tokens = line.split(" ");
                long timestamp, threadId;
                try {
                    timestamp = Long.parseLong(tokens[3]);
                    threadId = Long.parseLong(tokens[1]);
                } catch (NumberFormatException e) {
                    throw new IOException("Invalid heap dump line: " + line, e);
                }

                // Add the thread snapshot to the list
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadId);
                threadSnapshots.add(threadSnapshot);
                lastThreadSnapshot = threadSnapshot;
            } else if (line.startsWith("STACKTRACE:")) {
                // Parse the stack trace line
                String[] tokens = line.split(" ");
                int depth = Integer.parseInt(tokens[1]);
                long[] stackFrameIds = new long[depth];
                for (int i = 0; i < depth; i++) {
                    stackFrameIds[i] = Long.parseLong(tokens[2 + i]);
                }

                // Add the stack trace to the last thread snapshot
                lastThreadSnapshot.addStackTrace(stackFrameIds);
            }
        }
    }

    return threadSnapshots;
}
